--- /dev/null
+++ b/backend/src/GithubApi/__tests__/parseIssueUrl.test.ts
@@ -0,0 +1,41 @@
+import { describe, it, expect } from 'vitest'
+import { GithubApi, InvalidIssueUrlError } from '../index.js'
+
+const g = new GithubApi()
+
+describe('parseIssueUrl', () => {
+  const valid = [
+    ['https://github.com/o/r/issues/12', { host: 'github.com', owner: 'o', repo: 'r', issueNumber: 12 }],
+    ['https://github.com/o/r/issues/12/', { host: 'github.com', owner: 'o', repo: 'r', issueNumber: 12 }],
+    ['https://www.github.com/o/r/issues/12', { host: 'github.com', owner: 'o', repo: 'r', issueNumber: 12 }],
+    ['https://github.com/o-r_._/repo.name/issues/1?foo=bar', { host: 'github.com', owner: 'o-r_._', repo: 'repo.name', issueNumber: 1 }],
+    ['https://enterprise.local/myorg/myrepo/issues/5', { host: 'enterprise.local', owner: 'myorg', repo: 'myrepo', issueNumber: 5 }],
+  ]
+
+  for (const [input, expected] of valid) {
+    it(`accepts ${input}`, () => {
+      // allow custom host via env
+      process.env.GITHUB_HOSTS = 'github.com,enterprise.local'
+      const res = g.parseIssueUrl(input as string)
+      expect(res).toEqual(expected)
+    })
+  }
+
+  const invalid = [
+    ['http://github.com/o/r/issues/1', 'Only https URLs are allowed'],
+    ['https://github.com/o/r/pull/5', 'Pull request URLs are not accepted'],
+    ['https://github.com/o/r/issues/0', 'Invalid issue number'],
+    ['https://github.com/o/r/issues/notnum', 'Invalid issue number'],
+    ['https://notgithub.com/o/r/issues/1', 'Unknown host'],
+    ['https://github.com/invalid!owner/repo/issues/1', 'Invalid owner or repo name'],
+    ['https://github.com/o/r/other/1', 'URL must point to an issue'],
+  ]
+
+  for (const [input, message] of invalid) {
+    it(`rejects ${input}`, () => {
+      process.env.GITHUB_HOSTS = 'github.com'
+      expect(() => g.parseIssueUrl(input as string)).toThrowError(InvalidIssueUrlError)
+      try { g.parseIssueUrl(input as string) } catch (e:any) { expect(e.message).toContain(message as string) }
+    })
+  }
+})
