     parseIssueUrl(issueUrl:string){
-        const parts = issueUrl.replace("https://github.com/","").split("/")
-        return {
-            owner:parts[0] ?? "",
-            repo:parts[1] ?? "",
-            issueNumber:parseInt(parts[3] ?? "0")
+        try {
+            const url = new URL(issueUrl)
+            if (url.protocol !== "https:") throw new InvalidIssueUrlError("Only https URLs are allowed")
+            let host = url.hostname.toLowerCase()
+            if (host.startsWith("www.")) host = host.slice(4)
+
+            const envHosts = (process.env.GITHUB_HOSTS ?? "github.com").split(",").map(h => h.trim().toLowerCase()).filter(Boolean)
+            if (!envHosts.includes(host)) throw new InvalidIssueUrlError("Unknown host")
+
+            const parts = url.pathname.split("/").filter(Boolean)
+            if (parts.length < 4) throw new InvalidIssueUrlError("Invalid issue URL")
+            const [owner = "", repo = "", kind = "", numStr = ""] = parts
+
+            if (kind.toLowerCase() === "pull" || kind.toLowerCase() === "pulls") throw new InvalidIssueUrlError("Pull request URLs are not accepted")
+            if (kind.toLowerCase() !== "issues") throw new InvalidIssueUrlError("URL must point to an issue")
+
+            const nameRe = /^[A-Za-z0-9_.-]+$/
+            if (!nameRe.test(owner) || !nameRe.test(repo)) throw new InvalidIssueUrlError("Invalid owner or repo name")
+
+            const issueNumber = Number(numStr)
+            if (!Number.isInteger(issueNumber) || issueNumber <= 0) throw new InvalidIssueUrlError("Invalid issue number")
+
+            return { host, owner, repo, issueNumber }
+        } catch (err) {
+            if (err instanceof InvalidIssueUrlError) throw err
+            throw new InvalidIssueUrlError("Invalid issue URL")
         }
     }

